    double iSV = 0;
    double iYeu = 0;

    // Luôn đếm theo LearningLevel để đảm bảo thống kê chính xác
    for (int j = 0; j < dtbData.Rows.Count; j++)
    {
        iSV += 1;
        string strLearningLevel = Convert.ToString(dtbData.Rows[j]["LearningLevel"]).Trim();

        if (strLearningLevel.Equals("Yếu", StringComparison.OrdinalIgnoreCase) || strLearningLevel.Equals("Kém", StringComparison.OrdinalIgnoreCase))
            iYeu += 1;
        else if (strLearningLevel.Equals("Trung bình", StringComparison.OrdinalIgnoreCase))
            iTB += 1;
        else if (strLearningLevel.Equals("TB khá", StringComparison.OrdinalIgnoreCase))
            iTBKha += 1;
        else if (strLearningLevel.Equals("Khá", StringComparison.OrdinalIgnoreCase))
            iKha += 1;
        else if (strLearningLevel.Equals("Giỏi", StringComparison.OrdinalIgnoreCase))
            iTot += 1;
        else if (strLearningLevel.Equals("Xuất sắc", StringComparison.OrdinalIgnoreCase))
            iXuatSac += 1;
    }

    if (iSV <= 0)
        iSV = 1;

    string strRow = "<table class='statistics'>"
        + "<tr>"
        + "<td class='caption'>Xếp loại</td><td class='caption'>SL</td><td class='caption'>Tỉ lệ</td>"
        + "<td class='caption'>Xếp loại</td><td class='caption'>SL</td><td class='caption'>Tỉ lệ</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Xuất sắc</td><td>" + iXuatSac.ToString() + "</td><td>" + Math.Round(iXuatSac * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Giỏi</td><td>" + iTot.ToString() + "</td><td>" + Math.Round(iTot * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>TB</td><td>" + iTB.ToString() + "</td><td>" + Math.Round(iTB * 100.0 / iSV, 2).ToString() + "%</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Khá</td><td>" + iKha.ToString() + "</td><td>" + Math.Round(iKha * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>Yếu</td><td>" + iYeu.ToString() + "</td><td>" + Math.Round(iYeu * 100.0 / iSV, 2).ToString() + "%</td>"
        + "</tr>";

    if (iTBKha > 0)
    {
        strRow += "<tr>"
            + "<td>TB khá</td><td>" + iTBKha.ToString() + "</td><td>" + Math.Round(iTBKha * 100.0 / iSV, 2).ToString() + "%</td>"
            + "<td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>"
            + "</tr>";
    }

    strRow += "</table>";
    return strRow;
}

